// ui_card.js
const STATE = require('STATE')
const statedb = STATE(__filename)
const { get } = statedb(fallback_module)
const net = require('net_helper')

module.exports = ui_card

async function ui_card (opts, invite) {
  const { id, sdb } = await get(opts.sid)
  const { drive } = sdb

  const on = {
    style: inject
  }

  const { io } = net(id)

  const el = document.createElement('div')
  const shadow = el.attachShadow({ mode: 'closed' })

  shadow.innerHTML = `
    <div class="ui-card">
      <div class="card-preview"></div>

      <div class="card-footer">
        <div class="card-title">Radio button</div>

        <div class="card-bookmark">
          <svg viewBox="0 0 24 24" fill="none">
            <path
              d="M6 3H18C18.5523 3 19 3.44772 19 4V21L12 16L5 21V4C5 3.44772 5.44772 3 6 3Z"
              stroke="currentColor"
              stroke-width="2"
              stroke-linecap="round"
              stroke-linejoin="round"
            />
          </svg>

          <span>100</span>
        </div>
      </div>
    </div>
  `

  const sheet = new CSSStyleSheet()
  shadow.adoptedStyleSheets = [sheet]

  await sdb.watch(onbatch)

  if (invite) io.accept(invite)

  return el

  async function onbatch (batch) {
    for (const { type, paths } of batch) {
      const data = await Promise.all(
        paths.map(path => drive.get(path).then(file => file.raw))
      )

      const handler = on[type] || (() => {})
      handler({ data })
    }
  }

  function inject ({ data }) {
    sheet.replaceSync(data[0])
  }
}

function fallback_module () {
  return {
    api: fallback_instance,
    _: {
      net_helper: { $: '' }
    }
  }

  function fallback_instance () {
    return {
      _: {
        net_helper: {
          0: ''
        }
      },

      drive: {
        'style/ui_card.css': {
          raw: `
            :host {
              display: block;
              width: 100%;
              height: 100%;
              box-sizing: border-box;
            }

            * {
              box-sizing: border-box;
            }

            .ui-card {
              width: 100%;
              height: 100%;
              background: #050505;
              border-radius: 28px;
              padding: 18px;
              display: flex;
              flex-direction: column;
              gap: 16px;
              overflow: hidden;
            }

            .card-preview {
              flex: 1;
              width: 100%;
              background: #0b0c0f;
              border-radius: 22px;
              min-height: 0;
            }

            .card-footer {
              display: flex;
              align-items: center;
              justify-content: space-between;
              gap: 12px;
            }

            .card-title {
              color: #ffffff;
              font-size: 16px;
              font-weight: 600;
              line-height: 1.2;
              letter-spacing: -0.02em;
            }

            .card-bookmark {
              display: flex;
              align-items: center;
              gap: 8px;
              color: #ffffff;
              flex-shrink: 0;
            }

            .card-bookmark svg {
              width: 18px;
              height: 18px;
              display: block;
            }

            .card-bookmark span {
              font-size: 16px;
              font-weight: 500;
            }
          `
        }
      }
    }
  }
}